INSERT INTO "block_text_block" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","heading","content","is_free") VALUES('vb5g6wzhub','v6nyb7vl9o','content','guide',NULL,'content',0,'Before You Go','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Don''t tip.","marks":["strong"]},{"type":"span","value":" Seriously, it''s not a thing here. Service is always included."}]},{"type":"paragraph","children":[{"type":"span","value":"Everyone speaks English.","marks":["strong"]},{"type":"span","value":" Don''t stress about the language barrier."}]},{"type":"paragraph","children":[{"type":"span","value":"Book ahead for dinner.","marks":["strong"]},{"type":"span","value":" Many of the best places are small and fill up fast."}]},{"type":"paragraph","children":[{"type":"span","value":"Trust your gut — and mine.","marks":["strong"]},{"type":"span","value":" If a place feels overpriced, it probably is."}]}]}}',1);
INSERT INTO "block_text_block" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","heading","content","is_free") VALUES('q9rp90vjj8','nw9rviesmj','content','guide',NULL,'content',0,'RVKFOODIE Tip','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Do not try to do all of this in one rushed Golden Circle day. Plan one sit-down experience and balance it with one casual stop. The Golden Circle is about pace — eat well, soak somewhere, and enjoy the drive."}]},{"type":"paragraph","children":[{"type":"span","value":"Food is part of the experience — not just a pit stop.","marks":["strong"]}]}]}}',1);
INSERT INTO "block_text_block" ("id","_root_record_id","_root_field_api_key","_parent_container_model_api_key","_parent_block_id","_parent_field_api_key","_depth","heading","content","is_free") VALUES('t1','7guc0nxad6','content','guide',NULL,'content',0,'Tips for Eating Out with Kids in Reykjavík','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Icelanders eat late.","marks":["strong"]},{"type":"span","value":" Dinner service starts at 17:00–18:00. If you go right when doors open, you’ll often have the place to yourself."}]},{"type":"paragraph","children":[{"type":"span","value":"Most places have highchairs.","marks":["strong"]},{"type":"span","value":" But they’re often the basic IKEA kind. If your child needs a specific setup, bring your own clip-on seat."}]},{"type":"paragraph","children":[{"type":"span","value":"Changing tables are rare.","marks":["strong"]},{"type":"span","value":" Outside of the bigger restaurants and shopping centres, you’ll mostly be improvising."}]},{"type":"paragraph","children":[{"type":"span","value":"Don’t stress about the kids.","marks":["strong"]},{"type":"span","value":" Reykjavík is extremely child-friendly as a culture. Nobody’s going to glare at you if your toddler is being a toddler."}]},{"type":"paragraph","children":[{"type":"span","value":"Book ahead for dinner.","marks":["strong"]},{"type":"span","value":" The best places are small. Mentioning you’re bringing kids when you book helps them seat you somewhere with more space."}]}]}}',1);
